const users = [{id: 'a', name: 'Alice'}, {id: 'b', name: 'Bob'}];

function findUser(id?: string) {
  if (!id) return users[0];
  return users.find(u => u.id === id);
}

// Version A
function createInvoice(items: {qty:number, price:number}[]) {
  if (items.some(i => i.qty <= 0)) throw new Error('Invalid quantity');
  return items.reduce((s, i) => s + i.qty * i.price, 0);
}

// Version B
function createInvoice(items: {qty:number, price:number}[]) {
  return items.reduce((s, i) => s + Math.max(0, i.qty) * i.price, 0);
}
